  for(JSONObject s:items){LinearLayout tile=col();int width=resume?220:142,height=resume?130:204;FrameLayout cover=poster(s,height);tile.addView(cover,new LinearLayout.LayoutParams(-1,dp(height)));if(resume){TextView play=control("▶","Continuar assistindo",()->startWatching(s));cover.addView(play,new FrameLayout.LayoutParams(dp(42),dp(42),Gravity.CENTER));ProgressBar progressBar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progressBar.setProgressTintList(android.content.res.ColorStateList.valueOf(RED));int duration=prefs.getInt(local("show_duration_"+s.optInt("id")),1),position=prefs.getInt(local("show_progress_"+s.optInt("id")),0);progressBar.setProgress(Math.min(99,(int)(position*100L/Math.max(1,duration))));cover.addView(progressBar,new FrameLayout.LayoutParams(-1,dp(3),Gravity.BOTTOM));}
   gap(tile,9);TextView name=label(s.optString("title"),14,WHITE);name.setMaxLines(1);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setTypeface(Typeface.DEFAULT_BOLD);tile.addView(name);TextView meta=label(resume?"Continuar de "+time(prefs.getInt(local("show_progress_"+s.optInt("id")),0)):s.optString("genre")+" · "+s.optString("rating"),11,MUTED);meta.setPadding(0,dp(5),0,0);tile.addView(meta);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(width),-2);lp.rightMargin=dp(12);cards.addView(tile,lp);tile.setOnClickListener(v->{if(resume)startWatching(s);else details(s,"catalog");});}
