 void renderCatalog(LinearLayout p,JSONArray items,String q,String genre,boolean search){p.removeAllViews();ArrayList<JSONObject> found=new ArrayList<>();for(int i=0;i<items.length();i++){JSONObject s=items.optJSONObject(i);if((genre.equals("Todos")||genre.equals(s.optString("genre")))&&(s.optString("title")+" "+s.optString("synopsis")).toLowerCase(new Locale("pt","BR")).contains(q.toLowerCase(new Locale("pt","BR"))))found.add(s);}
  if(found.isEmpty()){empty(p,"play",items.length()==0?"O palco está pronto":"Nenhuma história encontrada",items.length()==0?"As primeiras produções aparecerão aqui após aprovação. Que tal publicar a sua?":"Tente outro título ou gênero.");if(items.length()==0)button(p,"Criar minha primeira produção",RED,()->edit(null));return;}
  if(!search&&q.isEmpty()&&genre.equals("Todos")){
   int featuredId=pro.homeData.optInt("featured_id");for(int i=0;i<found.size();i++)if(found.get(i).optInt("id")==featuredId){JSONObject chosen=found.remove(i);found.add(0,chosen);break;}JSONObject featured=found.get(0);FrameLayout hero=poster(featured,430);p.addView(hero,new LinearLayout.LayoutParams(-1,dp(430)));View shade=new View(this);shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x00090d14,0x10090d14,0xff090d14}));hero.addView(shade,new FrameLayout.LayoutParams(-1,-1));TextView tag=label("HISTÓRIAS INDEPENDENTES",9,WHITE);tag.setLetterSpacing(.14f);tag.setPadding(dp(14),dp(14),dp(14),dp(14));hero.addView(tag,new FrameLayout.LayoutParams(-1,-2,Gravity.TOP));LinearLayout overlay=col();overlay.setPadding(dp(18),dp(16),dp(18),dp(12));TextView kicker=label("EM DESTAQUE",10,RED);kicker.setLetterSpacing(.18f);overlay.addView(kicker);gap(overlay,9);TextView title=title(overlay,featured.optString("title"),30);title.setMaxLines(2);title.setTypeface(Typeface.DEFAULT_BOLD);text(overlay,featured.optString("genre")+"   •   "+featured.optString("rating")+"   •   Série independente",11,0xffd0d3da);TextView synopsis=text(overlay,featured.optString("synopsis"),12,0xffc4c8d0);synopsis.setMaxLines(2);synopsis.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout actions=row();Button watch=button(actions,"▶  Assistir",RED,()->startWatching(featured));LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,dp(48),1);wp.rightMargin=dp(8);watch.setLayoutParams(wp);Button detail=button(actions,"ⓘ  Detalhes",CARD,()->details(featured,"catalog"));detail.setLayoutParams(new LinearLayout.LayoutParams(0,dp(48),1));overlay.addView(actions);hero.addView(overlay,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
   ArrayList<JSONObject> ongoing=new ArrayList<>();for(JSONObject s:found)if(prefs.getInt(local("show_progress_"+s.optInt("id")),0)>0)ongoing.add(s);shelf(p,"Continue assistindo",ongoing,true);shelf(p,"Acabaram de chegar",found,false);
   if(found.size()>3){for(String category:new String[]{"Drama","Romance","Suspense","Novela"}){ArrayList<JSONObject> group=new ArrayList<>();for(JSONObject s:found)if(category.equals(s.optString("genre")))group.add(s);if(group.size()>1&&group.size()!=found.size())shelf(p,category,group,false);}}
   pro.homeExtras(p);gap(p,24);LinearLayout creator=col();creator.setBackground(bg(CARD,16));creator.setPadding(dp(18),dp(18),dp(18),dp(12));text(creator,"SUA HISTÓRIA TAMBÉM TEM LUGAR AQUI",10,RED);title(creator,"Do seu roteiro para a tela.",20);text(creator,"Publique sua produção e encontre seu público.",12,MUTED);button(creator,"Conhecer o espaço do criador  →",CARD,()->mine());p.addView(creator);return;
  }
  for(int i=0;i<found.size();i+=2){LinearLayout row=row();row.setGravity(Gravity.TOP);for(int j=i;j<Math.min(found.size(),i+2);j++){JSONObject s=found.get(j);LinearLayout tile=col();FrameLayout cover=poster(s,230);tile.addView(cover,new LinearLayout.LayoutParams(-1,dp(230)));gap(tile,8);TextView name=title(tile,s.optString("title"),14);name.setMaxLines(2);text(tile,s.optString("genre"),11,MUTED);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,0,j==i?dp(10):0,dp(14));row.addView(tile,lp);tile.setOnClickListener(v->details(s,"catalog"));}if(i+1==found.size())row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));p.addView(row);}
 }
 void saveButton(LinearLayout target,JSONObject s){final boolean[] saved={false},ready={false},working={false};Button b=button(target,"＋  Minha lista",CARD,()->{});socialRequest("GET","/shows/"+s.optInt("id")+"/save",null,r->{saved[0]=r.getBoolean("saved");ready[0]=true;b.setText(saved[0]?"✓  Na minha lista":"＋  Minha lista");});b.setOnClickListener(v->{if(!ready[0]||working[0])return;working[0]=true;b.setEnabled(false);safe(()->socialRequest("POST","/shows/"+s.optInt("id")+"/save",obj("saved",!saved[0]),r->{working[0]=false;b.setEnabled(true);saved[0]=r.getBoolean("saved");prefs.edit().putBoolean(local("saved_"+s.optInt("id")),saved[0]).apply();b.setText(saved[0]?"✓  Na minha lista":"＋  Minha lista");}));handler.postDelayed(()->{working[0]=false;b.setEnabled(true);},15000);});}
