 void profile(){page("profile","Seu espaço","Uma conta para assistir e criar.",3,null);LinearLayout identity=col();identity.setGravity(Gravity.CENTER);identity.setPadding(0,dp(20),0,dp(24));TextView avatar=label(displayName().substring(0,1).toUpperCase(),34,WHITE);avatar.setGravity(Gravity.CENTER);avatar.setBackground(bg(0xff472239,50));FrameLayout avatarFrame=new FrameLayout(this);avatarFrame.setBackground(bg(0xff472239,50));avatarFrame.setClipToOutline(true);avatarFrame.addView(avatar,new FrameLayout.LayoutParams(-1,-1));String avatarData=prefs.getString(local("avatar"),"");if(!avatarData.isEmpty()){try{byte[] bytes=android.util.Base64.decode(avatarData,2);ImageView photo=new ImageView(this);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));avatarFrame.addView(photo,new FrameLayout.LayoutParams(-1,-1));}catch(Exception ignored){}}identity.addView(avatarFrame,new LinearLayout.LayoutParams(dp(82),dp(82)));avatarFrame.setContentDescription("Alterar foto de perfil");avatarFrame.setOnClickListener(v->pro.profileEditor());TextView change=label("Alterar foto",12,RED);change.setPadding(0,dp(8),0,0);identity.addView(change);change.setOnClickListener(v->pro.profileEditor());gap(identity,16);TextView name=title(identity,displayName(),24);name.setGravity(Gravity.CENTER);TextView mail=text(identity,email,13,MUTED);mail.setGravity(Gravity.CENTER);body.addView(identity);menu("user","Meu perfil público","Foto, biografia e produções",()->pro.profileEditor());menu("film","Estatísticas","Conheça seu público",()->pro.analytics());menu("heart","Seguindo","Séries e criadores acompanhados",()->pro.following());menu("film","Avisos","Novos episódios",()->pro.notifications());menu("film","Minhas produções","Gerencie séries, novelas e episódios",()->mine());menu("heart","Minha lista","Suas histórias salvas",()->saved());menu("settings","Configurações","Conta, privacidade e ajuda",()->settings());if(role.equals("admin"))menu("shield","Painel de administração","Revise e aprove novas produções",()->admin());gap(body,20);text(body,"CINEO / DRAMAS  •  versão 0.4.0",11,MUTED);}
