 void settings(){page("settings","Configurações","Deixe o Cineo do seu jeito.",3,()->profile());menu("play","Reprodução e dados","Qualidade econômica e sincronização",()->pro.dataSettings());menu("user","Nome, foto e biografia","Edite seu perfil público",()->pro.profileEditor());menu("shield","Alterar senha","Proteja o acesso à sua conta",()->password());menu("heart","Privacidade","Saiba onde ficam seus dados",()->info("Privacidade","Email e credenciais são gerenciados pelo Supabase Auth. Produções e vídeos são armazenados para análise e distribuição após aprovação.\n\nCurtidas, comentários e sua lista são salvos na sua conta. Comentários e o nome escolhido ficam visíveis aos espectadores. Nome, foto pública, biografia e progresso de reprodução também são guardados na conta. Uma cópia do progresso fica neste aparelho para continuar sem conexão.\n\nA sessão é guardada criptografada com o Android Keystore. Sua senha não fica salva no aplicativo."));menu("film","Ajuda para publicar","Formatos, análise e limites",()->info("Como publicar","1. Crie uma produção e preencha título, sinopse, gênero e classificação.\n2. Escolha uma capa.\n3. Adicione episódios MP4 de até 25 MB cada.\n4. Confirme que possui os direitos e envie para análise.\n5. Acompanhe o resultado em Minhas produções.\n\nSe precisar de correções, o motivo aparece na produção. Edite e envie novamente.\n\nO serviço usa uma estrutura gratuita com capacidade limitada."));gap(body,12);pill(body,"Email confirmado",GREEN);gap(body,16);button(body,"Sair da conta",CARD,()->new AlertDialog.Builder(this).setTitle("Sair do Cineo?").setMessage("Você poderá entrar novamente com seu email e senha.").setNegativeButton("Cancelar",null).setPositiveButton("Sair",(d,w)->call("POST","/logout",new JSONObject(),r->{clearSession();login(false);})).show());}
