 void password(){page("password","Alterar senha","Use uma senha de pelo menos 8 caracteres.",3,()->settings());EditText old=field(body,"SENHA ATUAL","Sua senha atual",true),pw=field(body,"NOVA SENHA","Nova senha",true),confirm=field(body,"CONFIRMAR NOVA SENHA","Repita a senha",true);button(body,"Salvar nova senha",RED,()->safe(()->{if(pw.length()<8||!pw.getText().toString().equals(confirm.getText().toString())){notice("Confira a nova senha e a confirmação.",true);return;}call("POST","/password",obj("current",old.getText().toString(),"password",pw.getText().toString()),r->{clearSession();login(false);notice("Senha alterada. Entre com a nova senha.",false);});}));}
