  if(!s.optString("reason").isEmpty()){LinearLayout why=col();why.setPadding(dp(16),dp(16),dp(16),dp(16));why.setBackground(outline(CARD,12));title(why,"Ajustes solicitados",16);text(why,s.optString("reason"),14,0xffff8ba7);body.addView(why);gap(body,14);}
